def standard():
    vals = set()
    for k in range(0, 49):
        x1 = k * 0.25
        x2 = x1 + 4
        if x2 > 12:
            break
        s1 = math.sin(math.pi*x1/6)
        s2 = math.sin(math.pi*x2/6)
        if abs(s1 - s2) < 1e-9 and abs(s1) > 1e-9:
            vals.add(round(4 / abs(s1), 6))
    assert len(vals) == 1
    return round(list(vals)[0])

def unique():
    return [standard()]
